/** Text every generated file carries. */
export const FILE_HEADER = '# Auto-generated by oagen. Do not edit.';
export const HEADER_DOC = 'Auto-generated by oagen from the OpenAPI spec; do not edit by hand.';

/** A generated file; always overwritten (oagen merges `__init__.py` files additively by default). */
export function file(path: string, content: string): { path: string; content: string; overwriteExisting: true } {
  return { path, content, overwriteExisting: true };
}
